WITH valid AS (SELECT *, CAST(txn_time AS DATE) AS txn_time_day, TRIM(merchant) AS clean_merchant, COALESCE(merchant, 'UNKNOWN') AS merchant_filled FROM transactions WHERE txn_time >= DATE '2023-08-08'), enriched AS (SELECT *, COUNT(amount) OVER w_ordered AS running_count_amount, MIN(amount) OVER w_ordered AS running_min_amount, SUM(amount) OVER w_ordered AS running_sum_amount, AVG(amount) OVER (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS amount_avg_2 FROM valid WHERE txn_time_day >= '2024-09-13' WINDOW w_ordered AS (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), deduped AS (SELECT *, RANK() OVER (PARTITION BY account_id, txn_type ORDER BY running_min_amount) AS row_num FROM enriched QUALIFY row_num = 1), scored AS (SELECT id, txn_type, is_flagged, merchant_filled, running_min_amount, amount_avg_2, row_num, DENSE_RANK() OVER (PARTITION BY merchant ORDER BY amount NULLS FIRST) AS amount_dense_rank, RANK() OVER (PARTITION BY MONTH(txn_time), account_id ORDER BY running_min_amount DESC NULLS LAST) AS running_min_amount_rank, LAST_VALUE(running_min_amount, TRUE) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_running_min_amount FROM deduped) SELECT id, is_flagged, merchant_filled, running_min_amount, amount_dense_rank, running_min_amount_rank, last_known_running_min_amount FROM scored ORDER BY running_min_amount_rank DESC NULLS LAST, id
